const input = $input.first().json;
const payload = input.body.payload;

if (!payload.module) throw new Error("Missing module");
if (!payload.id) throw new Error("Missing record id");
if (!payload.field_name) throw new Error("Missing field name");
if (payload.value === undefined) throw new Error("Missing value");

const apiPayload = {
  data: [{ [payload.field_name]: payload.value }]
};

const baseUrl = 'https://www.zohoapis.in';
const finalUrl = `${baseUrl}/crm/v2/${payload.module}/${payload.id}`;

const logObj = {
  module: payload.module,
  id: payload.id,
  field_name: payload.field_name,
  value: payload.value,
  url: finalUrl,
  request_body: apiPayload
};

console.log("[N8N UPDATE LOG]", JSON.stringify(logObj));

return {
  json: {
    ...input,
    final_url: finalUrl,
    api_payload: apiPayload,
    log_data: logObj
  }
};

const putResponse = $('HTTP Request Zoho Update1').first().json;
const inputParams = $('Prepare Zoho Update Payload1').first().json.log_data;

// 1. Check for PUT HTTP/network error
if (!putResponse || putResponse.error || (putResponse.statusCode && putResponse.statusCode >= 400)) {
  return {
    json: {
      success: false,
      error: putResponse?.message || putResponse?.error || `HTTP error ${putResponse?.statusCode || 'unknown'}`,
      details: putResponse
    }
  };
}

// 2. Check for Zoho API authentication or general server errors
if (putResponse.code && putResponse.code !== "SUCCESS" && !putResponse.data) {
  return {
    json: {
      success: false,
      error: putResponse.message || putResponse.code || "Zoho CRM API error",
      details: putResponse
    }
  };
}

const dataArray = putResponse.data;
if (!dataArray || !Array.isArray(dataArray) || dataArray.length === 0) {
  return {
    json: {
      success: false,
      error: "Invalid or empty response format from Zoho CRM",
      details: putResponse
    }
  };
}

const recordResult = dataArray[0];
if (recordResult.status !== "success" && recordResult.code !== "SUCCESS") {
  return {
    json: {
      success: false,
      error: recordResult.message || recordResult.code || "Zoho CRM update failed",
      details: putResponse
    }
  };
}

// 3. Since PUT succeeded, check the GET request output
let getResponse = null;
try {
  getResponse = $('HTTP Request Get Fresh Record1').first().json;
} catch (e) {
  // Node was not executed or threw error
}

if (!getResponse || getResponse.error || (getResponse.statusCode && getResponse.statusCode >= 400)) {
  return {
    json: {
      success: true, // The update itself succeeded!
      id: inputParams.id,
      module: inputParams.module,
      updated_field: inputParams.field_name,
      new_value: inputParams.value,
      updated_record: null,
      error_fetching_fresh_record: getResponse?.message || getResponse?.error || "HTTP error on GET",
      zoho_response: putResponse
    }
  };
}

const getDataArray = getResponse.data;
const freshRecord = (getDataArray && getDataArray.length > 0) ? getDataArray[0] : null;

return {
  json: {
    success: true,
    id: inputParams.id,
    module: inputParams.module,
    updated_field: inputParams.field_name,
    new_value: inputParams.value,
    updated_record: freshRecord,
    zoho_response: putResponse
  }
};

const response = $('HTTP Request Zoho Delete').first().json;

if (
    response.data &&
    response.data[0] &&
    response.data[0].status === "success"
) {
    return {
        json:{
            success:true,
            deleted:true,
            message:response.data[0].message,
            module:$('Prepare Zoho Delete Payload').first().json.body.payload.module,
            id:$('Prepare Zoho Delete Payload').first().json.body.payload.id
        }
    };
}

return {
    json:{
        success:false,
        deleted:false,
        error:
            response.data?.[0]?.message ||
            response.message ||
            "Delete failed.",
        zoho_response:response
    }
};

