const input = $input.first().json;
const payload = input.body.payload;

if (!payload.module)
    throw new Error("Missing module");

if (!payload.fields)
    throw new Error("Missing fields");

const baseUrl = "https://www.zohoapis.in";
const finalUrl = `${baseUrl}/crm/v2/${payload.module}`;

const apiPayload = {
    data: [payload.fields]
};

console.log("[N8N CREATE LOG]");
console.log(JSON.stringify({
    module: payload.module,
    url: finalUrl,
    body: apiPayload
}, null, 2));

return {
    json: {
        ...input,
        final_url: finalUrl,
        api_payload: apiPayload
    }
};

// Response from Zoho Create API
const createResponse = $('HTTP Request Zoho Create').first().json;

// Full created record (if GET succeeded)
let createdRecord = null;

try {
    createdRecord = $('HTTP Request Get Created Record').first().json.data?.[0] || null;
} catch (e) {
    createdRecord = null;
}

// Create successful
if (
    createResponse.data &&
    createResponse.data.length &&
    (
        createResponse.data[0].status === "success" ||
        createResponse.data[0].code === "SUCCESS"
    )
) {

    return {
        json: {
            success: true,
            message: "Record created successfully.",
            id: createResponse.data[0].details.id,
            module: $('Prepare Zoho Create Payload').first().json.body.payload.module,

            // Return full record if available, otherwise return create details
            created_record: createdRecord || createResponse.data[0].details,

            zoho_response: createResponse
        }
    };

}

// Create failed
return {
    json: {
        success: false,

        error:
            createResponse.data?.[0]?.message ||
            createResponse.message ||
            "Create failed.",

        zoho_response: createResponse
    }
};
